def get_embedding(text: str) -> list[float]:
    """Получить эмбеддинг с retry-логикой и увеличенным таймаутом."""
    last_exception = None
    for attempt in range(1, MAX_RETRIES + 1):
        try:
            response = httpx.post(
                EMBEDDINGS_URL,
                json={"text": text},
                timeout=EMBEDDING_TIMEOUT
            )
            response.raise_for_status()
            return response.json()["embedding"]
        except (httpx.ReadTimeout, httpx.ConnectTimeout, httpx.TimeoutException) as e:
            last_exception = e
            if attempt < MAX_RETRIES:
                delay = RETRY_DELAY * attempt
                print(f"  ⏳ Таймаут (попытка {attempt}/{MAX_RETRIES}). Повтор через {delay}с...")
                time.sleep(delay)
            else:
                print(f"  ❌ Все {MAX_RETRIES} попыток исчерпаны.")
    raise last_exception


def main():
    client = QdrantClient(url=QDRANT_URL)

    # Более надежный способ проверки и пересоздания коллекции
    try:
        client.get_collection(COLLECTION_NAME)
        print(f"Коллекция '{COLLECTION_NAME}' найдена. Удаляем для чистой загрузки...")
        client.delete_collection(COLLECTION_NAME)
    except Exception:
        print(f"Коллекция '{COLLECTION_NAME}' не найдена. Создаем новую...")

    client.create_collection(
        collection_name=COLLECTION_NAME,
        vectors_config=models.VectorParams(size=VECTOR_SIZE, distance=models.Distance.COSINE),
    )

    # Прогрев модели embeddings-сервиса первым запросом
    print("🔥 Прогрев модели embeddings-сервиса...")
    try:
        get_embedding("прогрев")
        print("✅ Модель прогрета.\n")
    except Exception as e:
        print(f"⚠️  Не удалось прогреть модель: {e}")
        print("   Продолжаем загрузку, но возможны таймауты на первых картах.\n")

    points = []
    for card in CARDS_DATA:
        text_to_embed = f"{card['name']} {card['arcana']} {card['keywords']} {card['upright']} {card['reversed']} {card['advice']}"
        try:
            vector = get_embedding(text_to_embed)
            points.append(models.PointStruct(
                id=card["id"],
                vector=vector,
                payload={
                    "name": card["name"],
                    "arcana": card["arcana"],
                    "keywords": card["keywords"],
                    "upright": card["upright"],
                    "reversed": card["reversed"],
                    "advice": card["advice"]
                }
            ))
            print(f"✅ [{card['id']:2d}/78] {card['name']}")
        except Exception as e:
            print(f"❌ [{card['id']:2d}/78] Ошибка для карты '{card['name']}': {e}")
            raise

    client.upsert(collection_name=COLLECTION_NAME, points=points)
    print(f"\n🎉 Успешно загружено {len(points)} карт в коллекцию '{COLLECTION_NAME}'.")


if __name__ == "__main__":
    main()
